-- Crear grupo MVP y cargar clientes
BEGIN;

-- Asegurar grupo MVP
INSERT INTO grupos_venta (nombre, moneda, activo)
SELECT 'MVP', 'USD', true
WHERE NOT EXISTS (SELECT 1 FROM grupos_venta WHERE UPPER(nombre)=UPPER('MVP'));

-- Limpiar clientes del grupo MVP
DELETE FROM clientes WHERE grupo_id=(SELECT id FROM grupos_venta WHERE UPPER(nombre)=UPPER('MVP') LIMIT 1);

